sys_ui_action.client_script_v2:
function onClick() {
    if (g_form.getValue('attribute_sync') == 'Attribute Sync is in progress') {
        g_form.addInfoMessage('Attribute Sync is already in progress');
    } else {
        //gs.eventQueue('x_hsb11_mss_c_proc.event_layer_custody.o', current);
        //new x_hsb11_mss_custod.MSS_Custody_Refresh_Trade_Data().createRecord(); 
		//added as part of story 4046 to introduce direct api call
        //var ga = new GlideAjax('x_hsb11_mss_custod.MSS_Custody_Refresh_Trade_Data');
        //ga.addParam('sysparm_name', 'createRecord');

		//Removed the logic of event queue and added below code as part of story MSSOTIQUBE-1816 to make an api first then creating a record into staging table to give high precedence to API call than backend processing
		var ga = new GlideAjax('x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils');
        ga.addParam('sysparm_name', 'refreshTradeDataAPICall');
		ga.getXMLAnswer(function(response) {
            g_form.setValue('attribute_sync', 'Attribute Sync is in progress');
        });

    }
}

sys_ui_action.script:
if (current.attribute_sync == 'Attribute Sync is in progress') {
    gs.addInfoMessage('Attribute Sync is already in progress');
    action.setRedirectURL(current);
} else {
    //Old way of working
	//gs.eventQueue('x_hsb11_mss_c_proc.event_layer_custody.o', current);

	//added as part of story 4046 to introduce direct api call
    //new x_hsb11_mss_custod.MSS_Custody_Refresh_Trade_Data().createRecord();

    //Removed the logic of event queue and added below code as part of story MSSOTIQUBE-1816 to make an api first then creating a record into staging table to give high precedence to API call than backend processing
    new x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils().refreshTradeDataAPICall(new GlideDateTime());
    current.attribute_sync = "Attribute Sync is in progress";
    current.update();
    action.setRedirectURL(current);
}
